    for p in range(golfers):
        s.add(group[w][p] >= 0)
        s.add(group[w][p] < groups_num)

for w in range(weeks):
    for g in range(groups_num):
        count = z3.Sum([z3.If(group[w][p] == g, 1, 0) for p in range(golfers)])
        s.add(count == group_size)

for p1 in range(golfers):
    for p2 in range(p1 + 1, golfers):
        same = z3.Sum([z3.If(group[w][p1] == group[w][p2], 1, 0) for w in range(weeks)])
        s.add(same <= 1)

print(s.check())

